SELECT r.fetched_at,r.id,x FROM (SELECT * FROM raw_record WHERE source_system='CTB' AND fetcher_identity='ctb-recipes' ORDER BY fetched_at DESC LIMIT 1) r CROSS JOIN LATERAL jsonb_array_elements(convert_from(r.payload_bytes,'UTF8')::jsonb->'data') x WHERE x->>'recipeId'='733';
SELECT trading_date,sum((adjustment->>'grossIncTax')::numeric) receipt_gross,sum((adjustment->>'grossExTax')::numeric) receipt_net,sum((adjustment->>'finalExTax')::numeric) final_net,sum((adjustment->>'amountExTax')::numeric) adjustment_net,sum((adjustment->>'amountIncTax')::numeric) adjustment_gross, count(*) lines FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1 ORDER BY 1;
SELECT trading_date,adjustment->>'type' adjustment_type,sum((adjustment->>'amountExTax')::numeric) net,count(*) lines FROM resolved_sale_line WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1,2 ORDER BY 1,2;
SELECT trading_date,sum(amount) gross,sum(amount-tax_amount) net,sum(discounted_amount) discounted,sum(discounted_amount-amount) difference FROM source_product_sale_fact WHERE superseded_at IS NULL AND trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1 ORDER BY 1;
